/* @lc app=leetcode id=2385 lang=kotlin */
class Solution { fun amountOfTime(root: TreeNode?, start: Int): Int = mutableMapOf<Int, MutableList<Int>>().also { g -> java.util.ArrayDeque<TreeNode>().apply { root?.let { add(it) } }.let { q -> generateSequence(q.poll()) { q.poll() }.all { n -> n.left?.let { l -> g.getOrPut(n.val) { mutableListOf() }.add(l.val).also { g.getOrPut(l.val) { mutableListOf() }.add(n.val) }.also { q.add(l) } }.run { n.right?.let { r -> g.getOrPut(n.val) { mutableListOf() }.add(r.val).also { g.getOrPut(r.val) { mutableListOf() }.add(n.val) }.also { q.add(r) } } ?: true } ?: true } } }.let { g -> generateSequence(setOf(start) to setOf(start)) { (layer, allVis) -> layer.flatMap { g[it] ?: emptyList() }.filter { it !in allVis }.toSet().let { next -> if (next.isEmpty()) null else next to (allVis + next) } }.count() - 1 } }